/**
 * Test flow for waitForEmailReply action
 * Demonstrates waiting for an email reply
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const testWaitForEmailReply = Flow(
    {
        $id: Now.ID['test_wait_for_email_reply_flow'],
        name: 'Test Wait For Email Reply',
        description: 'Tests the waitForEmailReply core action',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['test_wait_for_email_reply_trigger'] },
        {
            table: 'sys_email',
            condition: 'type=send',
            run_flow_in: 'background',
        }
    ),
    (_params) => {
        const result = wfa.action(
            action.core.waitForEmailReply,
            { $id: Now.ID['test_wait_for_email_reply_action'] },
            {
                record: wfa.dataPill(_params.trigger.current.sys_id, 'reference'),
                timeout_duration: Duration({ days: 1 }),
            }
        )

        wfa.action(
            action.core.log,
            { $id: Now.ID['test_wait_for_email_reply_log'] },
            {
                log_level: 'info',
                log_message: `waitForEmailReply outputs: email_reply=${wfa.dataPill(result.email_reply, 'string')}, state=${wfa.dataPill(result.state, 'string')}`,
            }
        )
    }
)
